/**
 * Leaving Haran
 * -------------
 * Jacob flees Laban by night; Rachel hides the teraphim in a saddle and sits on them; the two camps meet on the hill of Gilead. Stage: a night crossing of a river, a caravan of tents and children, a woman hiding an idol; dawn overtaking a pursuit on a stony hill.
 *
 * Palette 0x2a1a10 → 0x060402 · light: dawn · hero: calf
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./jacob-kit.js.
 */

import { THREE, createScene, water, cityGate, house, tent, oak, tree, well, flame, person, birds } from './jacob-kit.js';

const BG = 0x2a1a10;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3094128613, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* river: animated water between grassy banks */
    water(W, group, 260, 26, -0.4, 0x020101, 0x070502);
    W.ground(260, 95, 0, 60, 0x060402, { amp: 0.5, j: 0.3, flat: 24, fz: 54 });
    W.ground(260, 95, 0, -64, 0x050302, { amp: 0.6, j: 0.3, flat: 24, fz: -58 });
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x030201), [0, -0.05, 12.6]);
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x030201), [0, -0.05, -14.6]);

    /* hills: angular ridges on the horizon */
    const hills = W.grp(group, [0, 0, 0], { name: 'hills' });
    for (let i = 0; i < 9; i++) {
        const x = -130 + i * 32 + W.rr(-8, 8);
        W.add(hills, W.G('cone', W.rr(14, 28), W.rr(10, 24), 5), W.mat(0x050302), [x, 0, -95 - W.rr(0, 25)], { r: [0, W.r() * 3, 0] });
    }
    W.backdrop(hills);

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [-16, 0, -58], { name: 'city', r: [0, 0.06, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x060402, trim: 0x050302 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x060402 });
    }
    W.backdrop(city);

    /* camp: a circle of tents */
    tent(W, group, -1.6, 0, -5.0, 1.34, 0x8a6a44, W.r() * 6);
    tent(W, group, 8.2, 0, -23.9, 1.34, 0xd8c8a0, W.r() * 6);
    tent(W, group, 11.2, 0, -7.2, 1.25, 0xd8c8a0, W.r() * 6);

    /* trees: broadleaf shade */
    oak(W, group, -21.3, 0, -51.9, 1.27, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -27.9, 0, -49.3, 0.90, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 12.0, 0, -13.1, 1.20, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 0.6, 0, -24.9, 1.24, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -35.5, 0, -44.8, 1.23, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    tree(W, group, 22.8, 0, -1.8, 1.1);

    /* garden: shade trees around a well */
    well(W, group, -6.8, 0, 7.2, 1.1);

    /* hero: the golden calf */
    const calf = W.grp(group, [0, 0, 11], { name: 'calf', r: [0, 0.5, 0] });
    const gold = W.mat(0xe0b040, { metal: 0.6, rough: 0.3, emissive: 0x4a3008, ei: 0.35 });
    W.add(calf, W.G('box', 2.2, 1.2, 1.0), gold, [0, 1.5, 0]);
    W.add(calf, W.G('sph', 0.55, 6, 5), gold, [1.5, 2.3, 0]);
    W.add(calf, W.G('cone', 0.12, 0.5, 4), gold, [1.9, 2.9, 0.25], { r: [0, 0, -0.5] });
    W.add(calf, W.G('cone', 0.12, 0.5, 4), gold, [1.9, 2.9, -0.25], { r: [0, 0, -0.5] });
    for (const [lx, lz] of [[0.7, 0.35], [0.7, -0.35], [-0.7, 0.35], [-0.7, -0.35]]) {
        W.add(calf, W.G('cyl', 0.16, 0.13, 1.2, 5), gold, [lx, 0.6, lz]);
    }
    W.add(calf, W.G('cyl', 0.06, 0.09, 2.2, 4), gold, [-1.2, 2.6, 0], { r: [0, 0, 1.0] });
    W.point(0xffc860, 1.8, 45, 0, 3, 11, 0.25);

    /* figures */
    person(W, group, [-5, 0, 16], { robe: 0x2a1a10, bend: 0.2, armR: [0.35, 0.1], armL: [-0.35, -0.1], ry: 0.12, s: 1.09 });
    person(W, group, [4.5, 0, 17], { robe: 0x060402, bend: 0.2, armR: [0.35, 0.1], armL: [-0.35, -0.1], ry: 0.41, s: 1.00 });

    /* birds: slow circles high above */
    birds(W, group, 6, 55, { y: 26 });

    return W.finish();
}

export default { build };
